"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["92528"],{99719(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.termo_consentimento.base_legal_tamanho","status":422,"titulo":"Tamanho da base legal do rascunho inv\xe1lido"},"descricao":{"codigo":"uniplus.configuracao.termo_consentimento.base_legal_tamanho","requisitos":[],"oQueAconteceu":["O campo `baseLegalRascunho`, no cadastro (`POST /api/configuracao/admin/termos-consentimento`) ou na edi\xe7\xe3o do rascunho (`PUT /api/configuracao/admin/termos-consentimento/{id}/rascunho`), tem mais de 500 caracteres. O c\xf3digo \xe9 conferido como recebido.","A recusa vem na lista `errors` da resposta, com `field` igual a `baseLegalRascunho`. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado; na edi\xe7\xe3o, o rascunho continua como estava, inclusive a marca de revis\xe3o. Na edi\xe7\xe3o, o `id` do corpo diferente do da rota \xe9 recusado com 400 antes das demais confer\xeancias, e em seguida o corpo \xe9 conferido, antes da busca do termo: um `{id}` que n\xe3o existe s\xf3 responde como n\xe3o encontrado quando o corpo \xe9 v\xe1lido."],"comoResolver":["Reduza a base legal a at\xe9 500 caracteres e envie de novo."],"ondeAparece":["Cadastro de um termo de consentimento","Edi\xe7\xe3o do rascunho de um termo de consentimento"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Termo consentimento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);